head.script:
scwin.test = function() {
	$w.log("main" + "_initScript");
};

scwin.test2 = function() {
	$w.log("main" + "_initScript2");
};

scwin.post1 = function() {
	$w.log("main" + "_postScript1");
};

scwin.post2 = function() {
	$w.log("main" + "_postScript2");
};

scwin.onpageload = function() {
	$w.log("main" + "_onpageload");
};

scwin.checkLog = function() {
	var log = WebSquare.logger.getLog();
	var check = true;
	check = check && (log.indexOf("[STEP7][EVENT]") < log.indexOf("w2_w2_initScript"));
	check = check && (log.indexOf("w2_w2_initScript") < log.indexOf("[STEP8][INITSCRIPT]"));
	check = check && (log.indexOf("[STEP7][EVENT]") < log.indexOf("w1_w1_onpageload"));
	check = check && (log.indexOf("[STEP8][INITSCRIPT]") < log.indexOf("w1_w1_onpageload"));
	check = check && (log.indexOf("w1_w1_onpageload") < log.indexOf("[STEP9][ONPAGELOAD]"));
	check = check && (log.indexOf("[STEP8][INITSCRIPT]") < log.indexOf("w2_w2_postScript2"));
	check = check && (log.indexOf("[STEP9][ONPAGELOAD]") < log.indexOf("w2_w2_postScript2"));
	return check;
};
